import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_activation_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_activation_kernel(const float* input, float* output,
                                       int batch_size, int channels,
                                       int D, int H, int W) {
    int idx = blockIdx.x;
    int spatial_size = D * H * W;
    int b = idx / spatial_size;
    int spatial_idx = idx % spatial_size;
    int d = spatial_idx / (H * W);
    int hw = spatial_idx % (H * W);
    int h = hw / W;
    int w = hw % W;

    int c = threadIdx.x;
    if (c >= channels) return;

    const float* input_ptr = input + b*channels*D*H*W + d*H*W*channels + h*W*channels + w*channels + c;
    float* output_ptr = output + b*channels*D*H*W + d*H*W*channels + h*W*channels + w*channels + c;

    float x = *input_ptr;

    __shared__ float s_max[1024];
    __shared__ float s_sum[1024];
    s_max[c] = x;
    __syncthreads();

    for (int stride = blockDim.x/2; stride > 0; stride >>= 1) {
        if (c < stride && s_max[c] < s_max[c+stride]) {
            s_max[c] = s_max[c+stride];
        }
        __syncthreads();
    }

    float max_val = s_max[0];
    float exp_val = expf(x - max_val);
    s_sum[c] = exp_val;
    __syncthreads();

    for (int stride = blockDim.x/2; stride > 0; stride >>= 1) {
        if (c < stride) {
            s_sum[c] += s_sum[c+stride];
        }
        __syncthreads();
    }

    float sum_val = s_sum[0];
    float result = 1.0f / (1.0f + expf(-(exp_val / sum_val)));
    *output_ptr = result;
}

torch::Tensor fused_activation_cuda(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 5, "Input must be 5D tensor");
    TORCH_CHECK(input.is_cuda(), "Input must be on CUDA");
    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    auto output = torch::empty_like(input);
    dim3 threads(channels);
    int total_blocks = batch_size * D * H * W;
    dim3 grid(total_blocks);

    fused_activation_kernel<<<grid, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        D,
        H,
        W
    );

    return output;
}
"""

fused_activation_cpp = "torch::Tensor fused_activation_cuda(torch::Tensor input);"

fused_activation = load_inline(
    name='fused_activation',
    cpp_sources=fused_activation_cpp,
    cuda_sources=fused_activation_source,
    functions=['fused_activation_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias=True):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding,
            output_padding=output_padding, bias=bias
        )
        self.activation = fused_activation

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.activation.fused_activation_cuda(x)
        return x
